class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        def can(seconds: int) -> bool:
            last = [0] * (n + 1)

            for pos in range(1, seconds + 1):
                last[changeIndices[pos - 1]] = pos

            for i in range(1, n + 1):
                if last[i] == 0:
                    return False

            free = 0
            for pos in range(1, seconds + 1):
                idx = changeIndices[pos - 1]

                if last[idx] == pos:
                    if nums[idx - 1] > free:
                        return False
                    free -= nums[idx - 1]
                else:
                    free += 1

            return True

        left, right = 1, m
        answer = -1

        while left <= right:
            mid = (left + right) // 2

            if can(mid):
                answer = mid
                right = mid - 1
            else:
                left = mid + 1

        return answer
