class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        if k == 26:
            return 1

        import sys
        from functools import lru_cache

        sys.setrecursionlimit(max(1000000, len(s) * 2))
        n = len(s)
        chars = [ord(ch) - ord('a') for ch in s]

        @lru_cache(None)
        def dfs(i: int, mask: int, can_change: bool) -> int:
            if i == n:
                return 1

            c = chars[i]

            # Do not change s[i]
            new_mask = mask | (1 << c)
            if new_mask.bit_count() > k:
                best = 1 + dfs(i + 1, 1 << c, can_change)
            else:
                best = dfs(i + 1, new_mask, can_change)

            # Change s[i] to any lowercase letter
            if can_change:
                for x in range(26):
                    new_mask = mask | (1 << x)
                    if new_mask.bit_count() > k:
                        candidate = 1 + dfs(i + 1, 1 << x, False)
                    else:
                        candidate = dfs(i + 1, new_mask, False)

                    if candidate > best:
                        best = candidate

            return best

        return dfs(0, 0, True)
